-- Jednorázové založení nové prázdné databáze/větve Neon pro Kam ven?.
-- Vygenerováno z migrací db/001 až 004
-- a místní databáze data/measurements.sqlite. Neobsahuje přístupové údaje.
-- Počty při vytvoření: 300 destinací, 115 přijatých měření,
-- 498 prověřených scén, 497 pokusů synchronizace.
-- Nespouštějte podruhé ani na větvi s existujícím katalogem destinací.
BEGIN;
-- Pevný katalog 300 cílů, otisk a38354bfa7b3b961ca3253ea4ed658582d033da58e11d953e65b2747a2d76581. Spusťte jednou na prázdné větvi Neonu.
CREATE TABLE IF NOT EXISTS public.destinations (
  id text PRIMARY KEY,
  name text NOT NULL,
  category text NOT NULL,
  latitude double precision NOT NULL CHECK (latitude BETWEEN -90 AND 90),
  longitude double precision NOT NULL CHECK (longitude BETWEEN -180 AND 180),
  record jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM public.destinations) THEN
    RAISE EXCEPTION 'Destination catalog is not empty; seed must only run once';
  END IF;
END $$;
DO $$ BEGIN
  IF (SELECT count(*) FROM public.destinations) <> 300 THEN
    RAISE EXCEPTION 'Destination catalog must contain exactly 300 rows';
  END IF;
END $$;
CREATE OR REPLACE FUNCTION public.reject_destination_changes() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'Destination catalog is frozen; use a reviewed migration to change it';
END $$;
CREATE TRIGGER destinations_frozen_rows BEFORE INSERT OR UPDATE OR DELETE ON public.destinations
  FOR EACH ROW EXECUTE FUNCTION public.reject_destination_changes();
CREATE TRIGGER destinations_frozen_truncate BEFORE TRUNCATE ON public.destinations
  FOR EACH STATEMENT EXECUTE FUNCTION public.reject_destination_changes();

-- Připravuje cloudové ukládání skutečných NDVI a FSC měření. Spusťte po 001.
CREATE TABLE IF NOT EXISTS public.satellite_measurements (
  place_id text NOT NULL REFERENCES public.destinations(id) ON DELETE RESTRICT,
  mode text NOT NULL CHECK (mode IN ('green', 'snow')),
  scene_id text NOT NULL,
  scene_date date NOT NULL,
  value double precision NOT NULL,
  valid_fraction double precision NOT NULL CHECK (valid_fraction BETWEEN 0.7 AND 1),
  cloud_fraction double precision NOT NULL CHECK (cloud_fraction BETWEEN 0 AND 0.3),
  source_url text NOT NULL CHECK (source_url LIKE 'https://%'),
  product text NOT NULL,
  statistic text NOT NULL,
  radius_meters integer NOT NULL DEFAULT 250 CHECK (radius_meters = 250),
  acquired_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (place_id, mode, scene_id),
  CHECK ((mode = 'green' AND product = 'S2-L2A-NDVI' AND statistic = 'median' AND value BETWEEN -1 AND 1)
    OR (mode = 'snow' AND product = 'CLMS-FSC-20M' AND statistic = 'mean' AND value BETWEEN 0 AND 100))
);

CREATE TABLE IF NOT EXISTS public.satellite_scene_checks (
  place_id text NOT NULL REFERENCES public.destinations(id) ON DELETE RESTRICT,
  mode text NOT NULL CHECK (mode IN ('green', 'snow')),
  scene_id text NOT NULL,
  checked_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (place_id, mode, scene_id)
);

CREATE TABLE IF NOT EXISTS public.satellite_sync_attempts (
  place_id text NOT NULL REFERENCES public.destinations(id) ON DELETE RESTRICT,
  mode text NOT NULL CHECK (mode IN ('green', 'snow')),
  attempted_at timestamptz NOT NULL,
  PRIMARY KEY (place_id, mode)
);

CREATE OR REPLACE VIEW public.latest_satellite_measurements AS
  SELECT DISTINCT ON (place_id, mode) * FROM public.satellite_measurements
  ORDER BY place_id, mode, scene_date DESC, acquired_at DESC;


-- Spusťte jednou po 002 (nebo po neon-bootstrap.sql) na existující větvi Neonu.
-- Čas pořízení snímku může chybět; nikdy jej nenahrazujeme časem importu.
ALTER TABLE public.satellite_measurements
  ADD COLUMN IF NOT EXISTS observed_at timestamptz;

-- Kompaktní název produktu Sentinel-2 obsahuje UTC čas začátku snímání.
-- Doplňujeme pouze záznamy, jejichž jméno a uložené datum souhlasí.
UPDATE public.satellite_measurements
SET observed_at = make_timestamptz(
  substr(scene_id, 12, 4)::integer,
  substr(scene_id, 16, 2)::integer,
  substr(scene_id, 18, 2)::integer,
  substr(scene_id, 21, 2)::integer,
  substr(scene_id, 23, 2)::integer,
  substr(scene_id, 25, 2)::double precision,
  'UTC'
)
WHERE observed_at IS NULL
  AND mode = 'green'
  AND scene_id ~ '^S2[ABCD]_MSIL2A_[0-9]{8}T[0-9]{6}_'
  AND substr(scene_id, 12, 4) || '-' || substr(scene_id, 16, 2) || '-' || substr(scene_id, 18, 2) = scene_date::text;

CREATE OR REPLACE VIEW public.latest_satellite_measurements AS
  SELECT DISTINCT ON (place_id, mode)
    place_id, mode, scene_id, scene_date, value, valid_fraction, cloud_fraction,
    source_url, product, statistic, radius_meters, acquired_at, observed_at
  FROM public.satellite_measurements
  ORDER BY place_id, mode, scene_date DESC, acquired_at DESC;

-- Přehled pro SQL Editor: jedno místo na řádek, NDVI a FSC vedle sebe.
-- NULL znamená, že pro daný režim neexistuje přijaté měření; 0 je platná hodnota.
CREATE OR REPLACE VIEW public.destination_satellite_overview AS
  SELECT
    d.id AS place_id, d.name AS place_name, d.latitude, d.longitude,
    g.value AS ndvi_median, g.scene_date AS ndvi_date,
    g.observed_at AS ndvi_observed_at, g.acquired_at AS ndvi_saved_at,
    g.valid_fraction AS ndvi_valid_fraction, g.cloud_fraction AS ndvi_cloud_fraction,
    g.scene_id AS ndvi_scene_id, g.source_url AS ndvi_source_url,
    s.value AS snow_fraction_percent, s.scene_date AS snow_date,
    s.observed_at AS snow_observed_at, s.acquired_at AS snow_saved_at,
    s.valid_fraction AS snow_valid_fraction, s.cloud_fraction AS snow_cloud_fraction,
    s.scene_id AS snow_scene_id, s.source_url AS snow_source_url
  FROM public.destinations AS d
  LEFT JOIN public.latest_satellite_measurements AS g ON g.place_id = d.id AND g.mode = 'green'
  LEFT JOIN public.latest_satellite_measurements AS s ON s.place_id = d.id AND s.mode = 'snow';
