UPDATE public.satellite_measurements SET observed_at = '2026-11-05T10:17:01.891Z' WHERE place_id = 'wd-Q97746745' AND mode = 'green' AND scene_id = 'S2A_MSIL2A_20261105T101121_N0513_R022_T33UUR_20261105T164009.SAFE';
-- Zimní žebříček používá pouze snímky od 1. prosince do konce února.
-- Jiná skutečná měření zůstávají v historii, ale nejsou posledním zimním výsledkem.
CREATE OR REPLACE VIEW public.latest_satellite_measurements AS
  SELECT DISTINCT ON (place_id, mode)
    place_id, mode, scene_id, scene_date, value, valid_fraction, cloud_fraction,
    source_url, product, statistic, radius_meters, acquired_at, observed_at
  FROM public.satellite_measurements
  WHERE mode <> 'snow' OR extract(month FROM scene_date) IN (12, 1, 2)
  ORDER BY place_id, mode, scene_date DESC, acquired_at DESC;
DO $$ BEGIN
  IF (SELECT count(*) FROM public.destinations) <> 300 OR
     (SELECT count(*) FROM public.satellite_measurements) <> 115 OR
     (SELECT count(*) FROM public.satellite_scene_checks) <> 498 OR
     (SELECT count(*) FROM public.satellite_sync_attempts) <> 497 THEN
    RAISE EXCEPTION 'Neon bootstrap row counts do not match the local snapshot';
  END IF;
END $$;
COMMIT;

SELECT (SELECT count(*) FROM public.destinations) AS destinations,
       (SELECT count(*) FROM public.satellite_measurements) AS measurements,
       (SELECT count(*) FROM public.satellite_scene_checks) AS scene_checks,
       (SELECT count(*) FROM public.satellite_sync_attempts) AS sync_attempts;
